'use strict';

// =============================================================================
// SCHEMA INVENTORY — what the database actually contains, read from the database
// =============================================================================
//
// This is the machine-checkable half of the schema documentation. The readable
// half (`docs/schema/schema.prisma`) is generated by Prisma and describes tables,
// columns and relations. Prisma's schema language CANNOT express triggers,
// functions, CHECK constraints, generated columns or partial indexes — measured
// on this database that is many hundreds of objects it cannot see (749 as this
// was written, and `docs/schema/beyond-prisma.json` carries the live count —
// a number quoted in a comment goes stale on the next migration and this one
// already has once), and a rebuild from that
// file alone would drop every one of them without an error.
//
// So this module records exactly the things Prisma is blind to, plus a compact
// fingerprint of every table and column, and it does it by READING THE CATALOG —
// never a hand-kept list, which is the kind that goes stale in silence.
//
// IT NEVER WRITES. Every statement here is a SELECT. It takes a `pg` client
// rather than opening its own connection, so a caller decides what it may reach
// and can hand it a read-only role.
//
// DETERMINISM IS THE WHOLE POINT: the output is committed and diffed, so the
// same database must always produce byte-identical output. Everything is sorted,
// and objects are built in a fixed key order.

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

/** Stable short hash of a function body — records CHANGE without carrying 100 KB of SQL. */
const bodyHash = (s) => crypto.createHash('sha256').update(String(s || '')).digest('hex').slice(0, 16);

const byName = (a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0);

async function tablesAndColumns(db) {
  const { rows } = await db.query(`
    SELECT c.table_name, c.column_name, c.data_type, c.is_nullable,
           c.is_generated, c.generation_expression, c.column_default
      FROM information_schema.columns c
      JOIN information_schema.tables t
        ON t.table_schema = c.table_schema AND t.table_name = c.table_name
     WHERE c.table_schema = 'public' AND t.table_type = 'BASE TABLE'
     ORDER BY c.table_name, c.column_name`);

  const tables = new Map();
  for (const r of rows) {
    if (!tables.has(r.table_name)) tables.set(r.table_name, []);
    // Compact, human-diffable, and carries the facts a consumer depends on:
    // the name, the type, and whether it may be absent.
    // THE DEFAULT IS PART OF THE COLUMN. Dropping `DEFAULT now()` changes what
    // every future row contains while the type and the nullability both stay
    // exactly as they were — so a signature without it reports "no change" on a
    // change that silently alters the data from then on.
    const def = (r.column_default || '').replace(/\s+/g, ' ').trim();
    tables.get(r.table_name).push(
      `${r.column_name} ${r.data_type}`
      + (r.is_nullable === 'NO' ? ' NOT NULL' : '')
      + (def ? ` DEFAULT ${def}` : '')
    );
  }
  return [...tables.entries()].sort((a, b) => (a[0] < b[0] ? -1 : 1))
    .map(([name, columns]) => ({ name, columns }));
}

async function generatedColumns(db) {
  const { rows } = await db.query(`
    SELECT table_name, column_name, generation_expression
      FROM information_schema.columns
     WHERE table_schema = 'public' AND is_generated = 'ALWAYS'
     ORDER BY table_name, column_name`);
  return rows.map((r) => ({
    name: `${r.table_name}.${r.column_name}`,
    expression: (r.generation_expression || '').replace(/\s+/g, ' ').trim(),
  })).sort(byName);
}

async function checkConstraints(db) {
  const { rows } = await db.query(`
    SELECT c.conname AS name, rel.relname AS table_name,
           pg_get_constraintdef(c.oid) AS definition
      FROM pg_constraint c
      JOIN pg_class rel ON rel.oid = c.conrelid
      JOIN pg_namespace n ON n.oid = c.connamespace
     WHERE c.contype = 'c' AND n.nspname = 'public'
     ORDER BY rel.relname, c.conname`);
  return rows.map((r) => ({
    name: r.name,
    table: r.table_name,
    definition: (r.definition || '').replace(/\s+/g, ' ').trim(),
  })).sort(byName);
}

async function triggers(db) {
  const { rows } = await db.query(`
    SELECT t.tgname AS name, rel.relname AS table_name,
           pg_get_triggerdef(t.oid) AS definition
      FROM pg_trigger t
      JOIN pg_class rel ON rel.oid = t.tgrelid
      JOIN pg_namespace n ON n.oid = rel.relnamespace
     WHERE NOT t.tgisinternal AND n.nspname = 'public'
     ORDER BY rel.relname, t.tgname`);
  return rows.map((r) => ({
    name: r.name,
    table: r.table_name,
    definition: (r.definition || '').replace(/\s+/g, ' ').trim(),
  })).sort(byName);
}

async function functions(db) {
  const { rows } = await db.query(`
    SELECT p.proname AS name,
           pg_get_function_identity_arguments(p.oid) AS args,
           pg_get_function_result(p.oid) AS returns,
           p.prosrc AS body
      FROM pg_proc p
      JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname = 'public'
     ORDER BY p.proname`);
  return rows.map((r) => ({
    name: `${r.name}(${r.args || ''})`,
    returns: r.returns,
    // The body is hashed rather than stored: a change is detected, the file
    // stays readable, and nobody is tempted to treat this as the source.
    bodyHash: bodyHash(r.body),
  })).sort(byName);
}

async function partialIndexes(db) {
  // ASK THE CATALOG WHETHER AN INDEX IS PARTIAL — never grep its definition text.
  // `pg_index.indpred` is Postgres's own record of the WHERE clause, so it is
  // the answer by construction. Matching `indexdef ILIKE '%WHERE%'` looks
  // equivalent and is not: it also matched `idx_market_obs_where`, an index that
  // merely has "where" in its NAME and is not partial at all. That single wrong
  // row is why the beyond-Prisma total was first reported as 737 rather than
  // 736 — a cheap string test producing a confidently wrong number, which is
  // exactly the shape the build rule in CLAUDE.md exists to forbid.
  const { rows } = await db.query(`
    SELECT c.relname AS name, rel.relname AS table_name,
           pg_get_indexdef(i.indexrelid) AS definition
      FROM pg_index i
      JOIN pg_class c ON c.oid = i.indexrelid
      JOIN pg_class rel ON rel.oid = i.indrelid
      JOIN pg_namespace n ON n.oid = c.relnamespace
     WHERE n.nspname = 'public' AND i.indpred IS NOT NULL
     ORDER BY rel.relname, c.relname`);
  return rows.map((r) => ({
    name: r.name,
    table: r.table_name,
    definition: (r.definition || '').replace(/\s+/g, ' ').trim(),
  })).sort(byName);
}

// =============================================================================
// THE RELATIONSHIP LAYER — what the first cut of this map left out entirely
// =============================================================================
//
// Owner-directed 2026-08-16: *"the database should get expanded and enhanced if
// something is being added. Let's enrich this even further."*
//
// The map began as tables, columns, and the five things Prisma cannot express.
// Measured against a real database, that left out **680 foreign keys, 797
// ordinary indexes, 321 primary keys, 37 unique constraints and 12 enum
// types** — so somebody could DROP A FOREIGN KEY, the map would not change,
// and the drift check would report everything as fine. A picture of a lending
// database that omits which loan belongs to which borrower is not a picture of
// it. Each section below is read from the CATALOG, so it grows on its own as
// the database grows; none of it is a list anybody maintains.

/** How each table is identified — one row per table, or the schema is broken. */
async function primaryKeys(db) {
  const { rows } = await db.query(`
    SELECT c.conname AS name, rel.relname AS table_name,
           pg_get_constraintdef(c.oid) AS definition
      FROM pg_constraint c JOIN pg_class rel ON rel.oid = c.conrelid
     WHERE c.contype = 'p' AND c.connamespace = 'public'::regnamespace
     ORDER BY rel.relname`);
  return rows.map((r) => ({
    name: r.name, table: r.table_name, definition: r.definition,
  })).sort(byName);
}

/** WHICH RECORD POINTS AT WHICH — the relationships, and what happens on delete. */
async function foreignKeys(db) {
  const { rows } = await db.query(`
    SELECT c.conname AS name, rel.relname AS table_name, tgt.relname AS references_table,
           pg_get_constraintdef(c.oid) AS definition
      FROM pg_constraint c
      JOIN pg_class rel ON rel.oid = c.conrelid
      JOIN pg_class tgt ON tgt.oid = c.confrelid
     WHERE c.contype = 'f' AND c.connamespace = 'public'::regnamespace
     ORDER BY rel.relname, c.conname`);
  // The definition carries ON DELETE CASCADE / SET NULL verbatim, which is the
  // part that decides whether deleting one row quietly removes a hundred others.
  return rows.map((r) => ({
    name: r.name, table: r.table_name, references: r.references_table,
    definition: r.definition,
  })).sort(byName);
}

/** What the database refuses to store twice. */
async function uniqueConstraints(db) {
  const { rows } = await db.query(`
    SELECT c.conname AS name, rel.relname AS table_name,
           pg_get_constraintdef(c.oid) AS definition
      FROM pg_constraint c JOIN pg_class rel ON rel.oid = c.conrelid
     WHERE c.contype = 'u' AND c.connamespace = 'public'::regnamespace
     ORDER BY rel.relname, c.conname`);
  return rows.map((r) => ({
    name: r.name, table: r.table_name, definition: r.definition,
  })).sort(byName);
}

/**
 * EVERY index, not only the partial ones.
 *
 * `partialIndexes` above records the subset Prisma cannot express; this records
 * all of them, because a dropped index does not change a single answer the
 * system gives — it changes how long the answer takes, which is the kind of
 * regression nobody attributes to a schema change months later.
 */
async function allIndexes(db) {
  const { rows } = await db.query(`
    SELECT c.relname AS name, rel.relname AS table_name,
           pg_get_indexdef(i.indexrelid) AS definition
      FROM pg_index i
      JOIN pg_class c ON c.oid = i.indexrelid
      JOIN pg_class rel ON rel.oid = i.indrelid
      JOIN pg_namespace n ON n.oid = c.relnamespace
     WHERE n.nspname = 'public'
     ORDER BY rel.relname, c.relname`);
  return rows.map((r) => ({
    name: r.name, table: r.table_name,
    definition: (r.definition || '').replace(/\s+/g, ' ').trim(),
  })).sort(byName);
}

/** The fixed lists of allowed values, and every value each one permits. */
async function enumTypes(db) {
  const { rows } = await db.query(`
    SELECT t.typname AS name, string_agg(e.enumlabel, ', ' ORDER BY e.enumsortorder) AS values
      FROM pg_type t JOIN pg_enum e ON e.enumtypid = t.oid
     WHERE t.typnamespace = 'public'::regnamespace
     GROUP BY t.typname ORDER BY t.typname`);
  return rows.map((r) => ({ name: r.name, values: r.values })).sort(byName);
}

/** Saved queries that look like tables. None today — recorded so one cannot appear unnoticed. */
async function views(db) {
  const { rows } = await db.query(`
    SELECT table_name AS name FROM information_schema.views
     WHERE table_schema = 'public' ORDER BY table_name`);
  return rows.map((r) => ({ name: r.name })).sort(byName);
}

/**
 * The whole inventory. Read-only. Deterministic.
 * @param {{query: Function}} db a `pg` client or pool
 */
async function buildInventory(db) {
  // SEQUENTIAL, NOT Promise.all. A single `pg` Client is one connection and one
  // wire protocol: overlapping queries on it is deprecated and will throw in
  // pg@9. Reading a catalog is fast, so there is nothing to gain by racing it.
  const tables = await tablesAndColumns(db);
  const generated = await generatedColumns(db);
  const checks = await checkConstraints(db);
  const trigs = await triggers(db);
  const funcs = await functions(db);
  const partials = await partialIndexes(db);
  // The relationship layer. Sequential for the same one-connection reason.
  const pks = await primaryKeys(db);
  const fks = await foreignKeys(db);
  const uniques = await uniqueConstraints(db);
  const indexes = await allIndexes(db);
  const enums = await enumTypes(db);
  const vws = await views(db);

  return {
    // A note to whoever opens the file, inside the file itself.
    _what: 'Generated by scripts/schema-snapshot.js — DO NOT EDIT BY HAND. '
         + 'This records what the database contains, including everything the Prisma '
         + 'schema cannot express. It is documentation and a drift check. '
         + 'NEVER rebuild a database from it.',
    counts: {
      tables: tables.length,
      columns: tables.reduce((n, t) => n + t.columns.length, 0),
      generatedColumns: generated.length,
      checkConstraints: checks.length,
      triggers: trigs.length,
      functions: funcs.length,
      partialIndexes: partials.length,
      primaryKeys: pks.length,
      foreignKeys: fks.length,
      uniqueConstraints: uniques.length,
      indexes: indexes.length,
      enums: enums.length,
      views: vws.length,
    },
    beyondPrisma: {
      generatedColumns: generated,
      checkConstraints: checks,
      triggers: trigs,
      functions: funcs,
      partialIndexes: partials,
    },
    // Expressible in Prisma, and every bit as much part of the picture.
    schema: {
      primaryKeys: pks,
      foreignKeys: fks,
      uniqueConstraints: uniques,
      indexes,
      enums,
      views: vws,
    },
    tables,
  };
}

/** How many objects Prisma's schema language cannot express. */
function beyondPrismaCount(inv) {
  const c = (inv && inv.counts) || {};
  return (c.generatedColumns || 0) + (c.checkConstraints || 0) + (c.triggers || 0)
       + (c.functions || 0) + (c.partialIndexes || 0);
}

/** Canonical text form — what gets written to disk and compared. */
const serialize = (inv) => JSON.stringify(inv, null, 2) + '\n';

/**
 * WHICH MIGRATIONS THIS CHECKOUT CONTAINS — read from `db/`, never from the
 * database, because there is no ledger table to read: `migrate.js` re-runs every
 * idempotent file on every boot and records nothing.
 *
 * The snapshot is stamped with this so the drift check can tell the two very
 * different kinds of drift apart, which is the whole reason it exists:
 *
 *   • the migration set MOVED  → somebody added a migration and did not
 *     regenerate the map. Ordinary, expected, fixed by one command.
 *   • the migration set is IDENTICAL and the schema still differs → the
 *     database contains something no migration in this repository explains.
 *     That is the alarming one, and without this stamp it reads exactly like
 *     the harmless case.
 */
function migrationState(dbDir) {
  const dir = dbDir || path.join(__dirname, '..', 'db');
  let files = [];
  try {
    files = fs.readdirSync(dir).filter((f) => /^\d+.*\.sql$/.test(f));
  } catch (_) {
    return null; // Unreadable is UNKNOWN, never a confident zero.
  }
  const nums = files.map((f) => parseInt(f, 10)).filter((n) => Number.isFinite(n));
  return {
    count: files.length,
    highest: nums.length ? Math.max(...nums) : null,
  };
}

// The section names the drift check walks. ONE list, so a section added above
// is compared automatically instead of being silently left unguarded — which is
// exactly how 680 foreign keys went unwatched in the first place.
const BEYOND_PRISMA_SECTIONS = ['triggers', 'functions', 'checkConstraints', 'generatedColumns', 'partialIndexes'];
const SCHEMA_SECTIONS = ['primaryKeys', 'foreignKeys', 'uniqueConstraints', 'indexes', 'enums', 'views'];

module.exports = {
  buildInventory, beyondPrismaCount, serialize, migrationState,
  BEYOND_PRISMA_SECTIONS, SCHEMA_SECTIONS,
  _internals: { bodyHash, byName },
};
